import { FilterXSS, getDefaultWhiteList } from 'xss';

// Server-side sanitizer for post HTML generated by draftjs-to-html.
// Runs in getStaticProps, so pages render pre-sanitized HTML.
//
// Uses `xss` (plain CommonJS, no DOM) on purpose: the Vercel server runtime
// fails to require() ESM-only packages (ERR_REQUIRE_ESM). That broke
// isomorphic-dompurify (via jsdom -> html-encoding-sniffer) and sanitize-html
// (via htmlparser2 v10) for every post page rendered on demand.
const whiteList = getDefaultWhiteList();
for (const tag of ['p', 'span', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'img', 'ins', 'del']) {
    whiteList[tag] = [...(whiteList[tag] ?? []), 'style'];
}
whiteList.a = ['href', 'title', 'target', 'rel'];

const filter = new FilterXSS({
    whiteList,
    stripIgnoreTagBody: ['script', 'style'],
    css: {
        whiteList: {
            'text-align': /^(left|right|center|justify)$/,
            'height': /^(\d+(px|%)?|auto)$/,
            'width': /^(\d+(px|%)?|auto)$/,
            'float': /^(left|right|none)$/,
        },
    },
});

export function sanitizePostHtml(html: string): string {
    return filter.process(html);
}
